        Convert a key bundle into a KeyJar instance.

        :return: An :py:class:`oidcmsg.key_jar.KeyJar` instance 
        """
        kj = KeyJar()
        for iss, k in self.bundle.items():
            try:
                kj.issuer_keys[iss] = k.issuer_keys[iss]
            except KeyError:
                kj.issuer_keys[iss] = k.issuer_keys['']
        return kj

